NoteWhat the symbols mean












Symbol
Meaning




\(A\)
Area: the space inside the circle (square units)


\(C\)
Circumference: the distance around the circle


\(d\)
Diameter: the distance across the circle, through the center


\(r\)
Radius: the distance from the center to the edge


\(\pi\)
Pi: about 3.14, the number of diameters that fit around a circle


\(\theta\)
Central angle, in degrees


\(^2\)
Squared: multiply a number by itself


\(\frac{1}{2}\)
One half








function memory(pairs) {
  const status = html`&lt;p&gt;&lt;/p&gt;`;
  const grid = html`&lt;div style="display:grid; grid-template-columns:repeat(4,1fr); gap:.5em; max-width:44em"&gt;&lt;/div&gt;`;
  const resetBtn = html`&lt;button class="btn btn-secondary mb-2"&gt;Reset & shuffle&lt;/button&gt;`;
  let open, found, timer;

  function deal() {                          // build a fresh board
    clearTimeout(timer);                     // cancel a pending flip-back
    open = []; found = 0;
    status.textContent = `Pairs found: 0 / ${pairs.length}`;
    grid.replaceChildren();                  // remove the old cards
    const cards = d3.shuffle(pairs.flatMap(([name, f], id) =&gt;
      [{id, face: () =&gt; html`&lt;b&gt;${name}&lt;/b&gt;`}, {id, face: () =&gt; tex`${f}`}]));

    for (const card of cards) {
      const btn = html`&lt;button class="btn btn-outline-primary" style="min-height:5em"&gt;?&lt;/button&gt;`;
      btn.onclick = () =&gt; {
        if (open.length === 2 || open.some(o =&gt; o.btn === btn)) return;   // ignore 3rd click / same card
        btn.replaceChildren(card.face());
        open.push({...card, btn});
        if (open.length &lt; 2) return;
        const [a, b] = open;
        if (a.id === b.id) {                                               // match: lock both cards
          for (const o of open) { o.btn.disabled = true; o.btn.className = "btn btn-success"; }
          open = [];
          status.textContent = ++found === pairs.length ? "All matched! 🎉" : `Pairs found: ${found} / ${pairs.length}`;
        } else {                                                           // no match: flip back
          timer = setTimeout(() =&gt; { for (const o of open) o.btn.textContent = "?"; open = []; }, 1200);
        }
      };
      grid.append(btn);
    }
  }

  resetBtn.onclick = deal;
  deal();
  return html`&lt;div&gt;${resetBtn}${status}${grid}&lt;/div&gt;`;
}







function wordle(lhs, answer, keys = ["π", "r", "d", "2", "²", "C", "θ", "½"], maxTries = 6) {
  const look = {                       // [tile classes, key classes] for each result
    success:   ["bg-success text-white",   "btn-success"],
    warning:   ["wordle-yellow",           "wordle-yellow"],
    secondary: ["bg-secondary text-white", "btn-secondary"]
  };
  const tileCls = "border rounded fs-4 d-inline-flex align-items-center justify-content-center";
  const board = html`&lt;div class="d-flex flex-column gap-1 mb-2"&gt;&lt;/div&gt;`;
  const msg = html`&lt;p style="min-height:1.5em"&gt;&lt;/p&gt;`;
  const kb = html`&lt;div class="d-flex flex-wrap gap-1 mb-3"&gt;&lt;/div&gt;`;
  const resetBtn = html`&lt;button class="btn btn-secondary"&gt;Reset&lt;/button&gt;`;
  const keyBtns = {};
  let typed, locked, row, tries, done;

  // Full guess: locked greens stay put; typed symbols fill the other blanks in order
  const full = () =&gt; { let j = 0; return answer.map((a, i) =&gt; locked[i] ? a : typed[j++]); };
  const blanks = () =&gt; locked.filter(x =&gt; !x).length;

  // Wordle rules: greens first, then yellows use up whatever answer symbols are left
  function score(g) {
    const left = answer.filter((a, i) =&gt; g[i] !== a);
    return g.map((s, i) =&gt;
      s === answer[i] ? "success"
      : left.includes(s) ? (left.splice(left.indexOf(s), 1), "warning")
      : "secondary");
  }

  function newRow() {
    row = html`&lt;div class="d-flex gap-1 align-items-center"&gt;&lt;span class="fs-4 me-2"&gt;${lhs}&lt;/span&gt;&lt;/div&gt;`;
    answer.forEach((a, i) =&gt; row.append(html`&lt;span class="${tileCls} ${locked[i] ? look.success[0] : ""}"
      style="width:2.2em; height:2.2em"&gt;${locked[i] ? a : ""}&lt;/span&gt;`));
    board.append(row);
  }

  function press(k) {
    if (done) return;
    if (k === "⌫") typed.pop();
    else if (k !== "Enter") { if (typed.length &lt; blanks()) typed.push(k); }
    else if (typed.length &lt; blanks()) { msg.textContent = "Fill every blank first."; return; }
    else {
      const g = full();
      score(g).forEach((c, i) =&gt; {
        row.children[i + 1].className = `${tileCls} ${look[c][0]}`;
        if (c === "success") locked[i] = true;                      // greens carry over to the next row
        const b = keyBtns[g[i]], rank = ["secondary", "warning", "success"].indexOf(c);
        if (rank &gt; b.rank) { b.rank = rank; b.className = `btn fs-5 ${look[c][1]}`; }  // keys keep their best color
      });
      tries++;
      if (locked.every(Boolean)) { done = true; msg.textContent = "Solved! 🎉"; }
      else if (tries === maxTries) { done = true; msg.textContent = `Out of tries. The answer is ${lhs} ${answer.join("")}`; }
      else { typed = []; newRow(); msg.textContent = ""; }
      return;
    }
    full().forEach((s, i) =&gt; row.children[i + 1].textContent = s ?? "");
  }

  function reset() {
    board.replaceChildren();
    typed = []; locked = answer.map(() =&gt; false); tries = 0; done = false; msg.textContent = "";
    for (const b of Object.values(keyBtns)) { b.rank = -1; b.className = "btn btn-outline-primary fs-5"; }
    newRow();
  }

  for (const k of [...keys, "⌫", "Enter"]) {
    keyBtns[k] = html`&lt;button style="min-width:2.5em"&gt;${k}&lt;/button&gt;`;
    keyBtns[k].onclick = () =&gt; press(k);
    kb.append(keyBtns[k]);
  }
  resetBtn.onclick = reset;
  reset();
  return html`&lt;div&gt;${board}${msg}${kb}${resetBtn}&lt;/div&gt;`;
}







// Shuffle buttons: put a carousel's slides in random order, show the new first one,
// and renumber the "1 of N" titles. Quiz questions also get renumbered in the Submit results.
// Games and answers keep any progress.
{
  for (const btn of document.querySelectorAll("[data-shuffle]")) {
    const inner = document.querySelector(btn.dataset.shuffle + " .carousel-inner");
    btn.onclick = () =&gt; d3.shuffle([...inner.children]).forEach((item, i) =&gt; {
      item.classList.toggle("active", i === 0);
      item.querySelector(".slide-num").textContent = i + 1;
      const form = item.querySelector(".quiz-question");
      if (form) form.dataset.question = `Question ${i + 1}`;
      inner.append(item);
    });
  }
}
